import React from 'react';
import { motion } from 'framer-motion';
import './Hero.css';

const Hero = () => {
  const fadeInUp = {
    initial: { opacity: 0, y: 60 },
    animate: { opacity: 1, y: 0 },
    transition: { duration: 0.6, ease: "easeOut" }
  };

  const staggerContainer = {
    animate: {
      transition: {
        staggerChildren: 0.2
      }
    }
  };

  const floatAnimation = {
    animate: {
      y: [0, -10, 0],
      transition: {
        duration: 3,
        repeat: Infinity,
        ease: "easeInOut"
      }
    }
  };

  const scaleIn = {
    initial: { scale: 0.8, opacity: 0 },
    animate: { 
      scale: 1, 
      opacity: 1,
      transition: {
        duration: 0.8,
        ease: "easeOut"
      }
    }
  };

  return (
    <section className="hero" id="hero">
      <div className="hero-overlay">
        <motion.div 
          className="animated-bg"
          animate={{
            backgroundPosition: ['0% 0%', '100% 100%'],
          }}
          transition={{
            duration: 20,
            repeat: Infinity,
            repeatType: "reverse",
            ease: "linear"
          }}
        />
      </div>

      <motion.div 
        className="floating-elements"
        initial="initial"
        animate="animate"
      >
        <motion.div className="floating-coffee" variants={floatAnimation}>☕</motion.div>
        <motion.div className="floating-cake" variants={floatAnimation}>🍰</motion.div>
        <motion.div className="floating-leaf" variants={floatAnimation}>🌿</motion.div>
      </motion.div>

      <div className="container hero-content">
        <motion.div
          className="hero-text"
          initial="initial"
          animate="animate"
          variants={staggerContainer}
        >
          <motion.div className="title-wrapper" variants={fadeInUp}>
            <motion.h1
              animate={{
                backgroundPosition: ['0% 50%', '100% 50%', '0% 50%'],
              }}
              transition={{
                duration: 5,
                repeat: Infinity,
                ease: "linear"
              }}
            >
              Welcome to Café Delight
            </motion.h1>
          </motion.div>
          
          <motion.div 
            className="hero-tagline"
            variants={fadeInUp}
          >
            <motion.span 
              className="highlight"
              whileHover={{ rotate: 360, scale: 1.2 }}
              transition={{ duration: 0.5 }}
            >
              ☕
            </motion.span>
            <motion.p
              animate={{
                opacity: [0.8, 1, 0.8],
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut"
              }}
            >
              Where Every Cup Tells a Story
            </motion.p>
            <motion.span 
              className="highlight"
              whileHover={{ rotate: 360, scale: 1.2 }}
              transition={{ duration: 0.5 }}
            >
              🍰
            </motion.span>
          </motion.div>

          <motion.p
            className="hero-description"
            variants={fadeInUp}
          >
            Experience the perfect blend of artisanal coffee and homemade delights in our cozy corner of comfort.
          </motion.p>

          <motion.div 
            className="hero-buttons"
            variants={fadeInUp}
          >
            <motion.a
              href="#menu"
              className="btn btn-primary"
              whileHover={{ scale: 1.05, boxShadow: "0 5px 15px rgba(0,0,0,0.1)" }}
              whileTap={{ scale: 0.95 }}
            >
              View Menu
            </motion.a>
            <motion.a
              href="#reservation"
              className="btn btn-outline"
              whileHover={{ scale: 1.05, boxShadow: "0 5px 15px rgba(0,0,0,0.1)" }}
              whileTap={{ scale: 0.95 }}
            >
              Reserve a Table
            </motion.a>
          </motion.div>
        </motion.div>

        <motion.div
          className="hero-image"
          variants={scaleIn}
          initial="initial"
          animate="animate"
          whileHover={{ scale: 1.02 }}
          transition={{ duration: 0.3 }}
        >
          <img 
            src="https://images.unsplash.com/photo-1442512595331-e89e73853f31?w=800&auto=format&fit=crop&q=60" 
            alt="Café Ambiance" 
          />
          <motion.div 
            className="image-overlay"
            animate={{
              background: [
                'linear-gradient(45deg, rgba(168, 208, 141, 0.2), rgba(245, 245, 220, 0.2))',
                'linear-gradient(45deg, rgba(245, 245, 220, 0.2), rgba(168, 208, 141, 0.2))',
              ]
            }}
            transition={{
              duration: 3,
              repeat: Infinity,
              repeatType: "reverse",
              ease: "linear"
            }}
          />
        </motion.div>
      </div>

      <motion.div
        className="scroll-down"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 1.5, duration: 0.8 }}
      >
        <motion.div 
          className="mouse"
          animate={{
            boxShadow: [
              "0 0 0 rgba(168, 208, 141, 0)",
              "0 0 20px rgba(168, 208, 141, 0.5)",
              "0 0 0 rgba(168, 208, 141, 0)"
            ]
          }}
          transition={{
            duration: 2,
            repeat: Infinity,
            ease: "easeInOut"
          }}
        >
          <div className="wheel"></div>
        </motion.div>
        <div className="arrow"></div>
      </motion.div>
    </section>
  );
};

export default Hero;
